    {'technology': 'mysql', 'topic': 'group-by', 'name': 'Group by Multiple Columns', 'slug': 'group-by-multiple-columns', 'description': "An orders table has columns id, customer_id, and amount, and a customers table has columns id and name. Write a query that returns each customer's name and the total amount they ordered, ordered by name alphabetically. Join the tables on customer_id.", 'input_format': 'There is no input; the customers and orders tables already exist with sample data.', 'output_format': "Print each customer's name and their total order amount.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50),(2,1,30),(3,2,20);", 'output': 'Ana|80\nBen|20'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 5, 'starter': '-- Join customers and orders, group by customer name, sum amount, ordered by name\n', 'tests': [("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50),(2,1,30),(3,2,20);", 'Ana|80\nBen|20\n', False, 1), ("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Cy'),(2,'Dee');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,10),(2,2,5),(3,2,5);", 'Cy|10\nDee|10\n', True, 1)], 'reference_query': 'SELECT customers.name, SUM(orders.amount) FROM customers JOIN orders ON orders.customer_id = customers.id GROUP BY customers.name ORDER BY customers.name;'},
    {'technology': 'mysql', 'topic': 'having', 'name': 'Groups Above a Count Threshold', 'slug': 'groups-above-a-count-threshold', 'description': 'An employees table has columns id, name, department, and salary. Write a query that returns each department that has more than 1 employee, along with its employee count, ordered by department.', 'input_format': 'There is no input; the employees table already exists with sample data.', 'output_format': 'Print each qualifying department and its employee count.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',1),(2,'Ben','IT',2),(3,'Cy','HR',3);", 'output': 'IT|2'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 1, 'starter': '-- Group by department, keep groups having COUNT(*) > 1, ordered by department\n', 'tests': [("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',1),(2,'Ben','IT',2),(3,'Cy','HR',3);", 'IT|2\n', False, 1), ("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Dee','Ops',1),(2,'Eli','IT',2),(3,'Fay','IT',3),(4,'Gus','HR',4);", 'IT|2\n', True, 1)], 'reference_query': 'SELECT department, COUNT(*) FROM employees GROUP BY department HAVING COUNT(*) > 1 ORDER BY department;'},
