    {'technology': 'mysql', 'topic': 'constraints', 'name': 'A Unique Column', 'slug': 'a-unique-column', 'description': 'Above the provided inspection query, write a CREATE TABLE statement for a table named t with columns id (INTEGER) and email (TEXT), where email must be unique. Then insert one row and confirm a second insert with the same email fails by catching it -- instead, just insert one row and select the count, which should be 1.', 'input_format': 'There is no input for this problem.', 'output_format': 'Print the row count after inserting one row.', 'constraints': 'None.', 'examples': [{'input': '', 'output': '1'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 4, 'starter': "-- Write CREATE TABLE t(id INTEGER, email TEXT UNIQUE), then INSERT INTO t VALUES (1, 'a@x.com')\n-- Do not modify the line below.\nSELECT COUNT(*) FROM t;\n", 'tests': [('', '1\n', False, 1)], 'reference_query': "CREATE TABLE t(id INTEGER, email TEXT UNIQUE);\nINSERT INTO t VALUES (1, 'a@x.com');\nSELECT COUNT(*) FROM t;"},
    {'technology': 'mysql', 'topic': 'constraints', 'name': 'A Foreign Key Reference', 'slug': 'a-foreign-key-reference', 'description': 'A parent table t_parent(id INTEGER PRIMARY KEY) already exists with one row (id 1). Above the provided inspection query, write a CREATE TABLE statement for a table named t_child with columns id (INTEGER) and parent_id (INTEGER), where parent_id references t_parent(id). Then insert a child row with parent_id 1.', 'input_format': 'There is no input; the t_parent table already exists with one row.', 'output_format': "Print the child row's id and parent_id after inserting it.", 'constraints': 'None.', 'examples': [{'input': 'CREATE TABLE t_parent(id INTEGER PRIMARY KEY);\nINSERT INTO t_parent VALUES (1);', 'output': '1|1'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 5, 'starter': '-- Write CREATE TABLE t_child(id INTEGER, parent_id INTEGER REFERENCES t_parent(id))\n-- then INSERT INTO t_child VALUES (1, 1)\n-- Do not modify the line below.\nSELECT id, parent_id FROM t_child;\n', 'tests': [('CREATE TABLE t_parent(id INTEGER PRIMARY KEY);\nINSERT INTO t_parent VALUES (1);', '1|1\n', False, 1)], 'reference_query': 'CREATE TABLE t_child(id INTEGER, parent_id INTEGER REFERENCES t_parent(id));\nINSERT INTO t_child VALUES (1, 1);\nSELECT id, parent_id FROM t_child;'},
    {'technology': 'mysql', 'topic': 'views', 'name': 'Create a Simple View', 'slug': 'create-a-simple-view', 'description': 'A students table has columns id, name, and score. Above the provided query, write a CREATE VIEW statement named passing_students that selects every student. The provided query then reads from your view.', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': 'The provided query prints every row from your view, ordered by id.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',59);", 'output': '1|Ana|82\n2|Ben|59'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 1, 'starter': '-- Write CREATE VIEW passing_students AS SELECT * FROM students\n-- Do not modify the line below.\nSELECT id, name, score FROM passing_students ORDER BY id;\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',59);", '1|Ana|82\n2|Ben|59\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Cy',91),(2,'Dee',40);", '1|Cy|91\n2|Dee|40\n', True, 1)], 'reference_query': 'CREATE VIEW passing_students AS SELECT * FROM students;\nSELECT id, name, score FROM passing_students ORDER BY id;'},
    {'technology': 'mysql', 'topic': 'views', 'name': 'Create a Filtered View', 'slug': 'create-a-filtered-view', 'description': 'A students table has columns id, name, and score. Above the provided query, write a CREATE VIEW statement named passing_students that only includes students scoring 60 or above.', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': 'The provided query prints every row from your view, ordered by id.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',40);", 'output': '1|Ana|82'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 2, 'starter': '-- Write CREATE VIEW passing_students AS SELECT * FROM students WHERE score >= 60\n-- Do not modify the line below.\nSELECT id, name, score FROM passing_students ORDER BY id;\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',40);", '1|Ana|82\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Cy',91),(2,'Dee',10),(3,'Eli',61);", '1|Cy|91\n3|Eli|61\n', True, 1)], 'reference_query': 'CREATE VIEW passing_students AS SELECT * FROM students WHERE score >= 60;\nSELECT id, name, score FROM passing_students ORDER BY id;'},
    {'technology': 'mysql', 'topic': 'views', 'name': 'Create a View With a Computed Column', 'slug': 'create-a-view-with-a-computed-column', 'description': 'A students table has columns id, name, and score. Above the provided query, write a CREATE VIEW statement named graded that selects id, name, and a computed column bonus_score equal to score + 10.', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': 'The provided query prints every row from your view, ordered by id.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',40);", 'output': '1|Ana|92\n2|Ben|50'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 3, 'starter': '-- Write CREATE VIEW graded AS SELECT id, name, score + 10 AS bonus_score FROM students\n-- Do not modify the line below.\nSELECT id, name, bonus_score FROM graded ORDER BY id;\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',40);", '1|Ana|92\n2|Ben|50\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Cy',91),(2,'Dee',10);", '1|Cy|101\n2|Dee|20\n', True, 1)], 'reference_query': 'CREATE VIEW graded AS SELECT id, name, score + 10 AS bonus_score FROM students;\nSELECT id, name, bonus_score FROM graded ORDER BY id;'},
    {'technology': 'mysql', 'topic': 'views', 'name': 'Create a View With a Join', 'slug': 'create-a-view-with-a-join', 'description': 'A customers table has columns id and name, and an orders table has columns id, customer_id, and amount. Above the provided query, write a CREATE VIEW statement named customer_orders that joins the two tables and selects customer name and order amount.', 'input_format': 'There is no input; the customers and orders tables already exist with sample data.', 'output_format': 'The provided query prints every row from your view, ordered by customer id then order id.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50),(2,2,20);", 'output': 'Ana|50\nBen|20'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 4, 'starter': '-- Write CREATE VIEW customer_orders AS SELECT ... JOIN ...\n-- Do not modify the line below.\nSELECT name, amount FROM customer_orders ORDER BY cid, oid;\n', 'tests': [("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50),(2,2,20);", 'Ana|50\nBen|20\n', False, 1), ("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Cy'),(2,'Dee');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,10),(2,1,15);", 'Cy|10\nCy|15\n', True, 1)], 'reference_query': 'CREATE VIEW customer_orders AS SELECT customers.id AS cid, orders.id AS oid, customers.name, orders.amount FROM customers JOIN orders ON orders.customer_id = customers.id;\nSELECT name, amount FROM customer_orders ORDER BY cid, oid;'},
    {'technology': 'mysql', 'topic': 'views', 'name': 'Query an Existing View', 'slug': 'query-an-existing-view', 'description': 'A view named top_students already exists (defined as students scoring 80 or above), backed by a students table with columns id, name, and score. Write a query against top_students that returns every name, ordered alphabetically.', 'input_format': 'There is no input; the students table and the top_students view already exist.', 'output_format': "Print each qualifying student's name, alphabetically.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',90),(2,'Ben',40),(3,'Cy',85);\nCREATE VIEW top_students AS SELECT * FROM students WHERE score >= 80;", 'output': 'Ana\nCy'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 5, 'starter': '-- Select name from top_students, ordered alphabetically\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',90),(2,'Ben',40),(3,'Cy',85);\nCREATE VIEW top_students AS SELECT * FROM students WHERE score >= 80;", 'Ana\nCy\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Dee',81),(2,'Eli',10);\nCREATE VIEW top_students AS SELECT * FROM students WHERE score >= 80;", 'Dee\n', True, 1)], 'reference_query': 'SELECT name FROM top_students ORDER BY name;'},
    {'technology': 'mysql', 'topic': 'index-fundamentals', 'name': 'Create an Index on a Column', 'slug': 'create-an-index-on-a-column', 'description': 'A students table has columns id, name, and score, and already contains data. Above the provided query, write a CREATE INDEX statement named idx_students_score on students(score).', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': 'The provided query lists the names of every index defined on students.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',59);", 'output': 'idx_students_score'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 1, 'starter': "-- Write CREATE INDEX idx_students_score ON students(score)\n-- Do not modify the line below.\nSELECT name FROM pragma_index_list('students') ORDER BY name;\n", 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',59);", 'idx_students_score\n', False, 1)], 'reference_query': "CREATE INDEX idx_students_score ON students(score);\nSELECT name FROM pragma_index_list('students') ORDER BY name;"},
