    {'technology': 'javascript', 'topic': 'loops', 'name': 'A For Loop Sum', 'slug': 'a-for-loop-sum', 'description': 'Read one positive integer n and print the sum of all integers from 1 through n, using a for loop.', 'input_format': 'One positive integer n.', 'output_format': 'Print 1 + 2 + ... + n.', 'constraints': 'None.', 'examples': [{'input': '5', 'output': '15'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 1, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\n// Sum 1..n with a for loop, then print it\n", 'tests': [('5\n', '15\n', False, 1), ('1\n', '1\n', False, 1), ('100\n', '5050\n', True, 2), ('10\n', '55\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\nlet total = 0;\nfor (let i = 1; i <= n; i++) {\n  total += i;\n}\nconsole.log(total);\n"},
    {'technology': 'javascript', 'topic': 'loops', 'name': 'A While Loop Countdown', 'slug': 'a-while-loop-countdown', 'description': 'Read one positive integer n and print each integer from n down to 1, one per line, using a while loop.', 'input_format': 'One positive integer n.', 'output_format': 'Print n, n-1, ..., 1, one per line.', 'constraints': 'None.', 'examples': [{'input': '3', 'output': '3\n2\n1'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 2, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nlet n = Number(input);\n// Print n down to 1 with a while loop\n", 'tests': [('3\n', '3\n2\n1\n', False, 1), ('1\n', '1\n', False, 1), ('5\n', '5\n4\n3\n2\n1\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nlet n = Number(input);\nwhile (n >= 1) {\n  console.log(n);\n  n--;\n}\n"},
    {'technology': 'javascript', 'topic': 'loops', 'name': 'Break Out of a Loop', 'slug': 'break-out-of-a-loop', 'description': 'Read one positive integer n and print the first integer greater than 0 that divides n evenly, starting the search from 2, using break once found. Assume n > 1.', 'input_format': 'One integer n > 1.', 'output_format': 'Print the smallest divisor of n that is >= 2.', 'constraints': 'None.', 'examples': [{'input': '15', 'output': '3'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 3, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\n// Find the smallest divisor of n >= 2, breaking once found\n", 'tests': [('15\n', '3\n', False, 1), ('7\n', '7\n', False, 1), ('100\n', '2\n', True, 2), ('2\n', '2\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\nlet divisor = 2;\nwhile (true) {\n  if (n % divisor === 0) {\n    break;\n  }\n  divisor++;\n}\nconsole.log(divisor);\n"},
    {'technology': 'javascript', 'topic': 'loops', 'name': 'Continue to Skip Values', 'slug': 'continue-to-skip-values', 'description': 'Read one positive integer n and print the sum of every even number from 1 through n, skipping odd numbers with continue.', 'input_format': 'One positive integer n.', 'output_format': 'Print the sum of the even numbers from 1 to n.', 'constraints': 'None.', 'examples': [{'input': '10', 'output': '30'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 4, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\n// Sum the even numbers from 1 to n, using continue to skip odds\n", 'tests': [('10\n', '30\n', False, 1), ('1\n', '0\n', False, 1), ('7\n', '12\n', True, 2), ('20\n', '110\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\nlet total = 0;\nfor (let i = 1; i <= n; i++) {\n  if (i % 2 !== 0) {\n    continue;\n  }\n  total += i;\n}\nconsole.log(total);\n"},
    {'technology': 'javascript', 'topic': 'loops', 'name': 'Nested Loops', 'slug': 'nested-loops-js', 'description': 'Read one positive integer n and print an n x n multiplication-style grid: for each row i from 1 to n, print the products i*1, i*2, ..., i*n, space-separated, one row per line.', 'input_format': 'One positive integer n.', 'output_format': 'Print n rows, each with n space-separated products.', 'constraints': 'None.', 'examples': [{'input': '2', 'output': '1 2\n2 4'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 5, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\n// Print an n x n multiplication grid\n", 'tests': [('2\n', '1 2\n2 4\n', False, 1), ('3\n', '1 2 3\n2 4 6\n3 6 9\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\nfor (let i = 1; i <= n; i++) {\n  const row = [];\n  for (let j = 1; j <= n; j++) {\n    row.push(i * j);\n  }\n  console.log(row.join(' '));\n}\n"},
