    {'technology': 'javascript', 'topic': 'arrays', 'name': 'Push and Pop', 'slug': 'push-and-pop', 'description': "Read a line of space-separated integers into an array, push the value 100 onto the end, then remove the first element with shift, and print the resulting array's elements space-separated.", 'input_format': 'One line of space-separated integers (at least one).', 'output_format': 'Print the resulting array, space-separated.', 'constraints': 'None.', 'examples': [{'input': '1 2 3', 'output': '2 3 100'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 2, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst values = input.split(' ').map(Number);\n// push(100), then shift(), then print\n", 'tests': [('1 2 3\n', '2 3 100\n', False, 1), ('5\n', '100\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst values = input.split(' ').map(Number);\nvalues.push(100);\nvalues.shift();\nconsole.log(values.join(' '));\n"},
