    {'technology': 'javascript', 'topic': 'arrays', 'name': 'Check if a Value Exists', 'slug': 'check-if-a-value-exists', 'description': 'Read a line of space-separated integers, then a second line with a single target integer. Print true if the target appears in the array, otherwise false.', 'input_format': 'Line 1: space-separated integers. Line 2: a target integer.', 'output_format': 'Print true or false.', 'constraints': 'None.', 'examples': [{'input': '1 2 3\n2', 'output': 'true'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 5, 'starter': "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\nconst values = lines[0].split(' ').map(Number);\nconst target = Number(lines[1]);\n// Print whether target is in values\n", 'tests': [('1 2 3\n2', 'true\n', False, 1), ('5 6 7\n9', 'false\n', False, 1), ('0\n0', 'true\n', True, 2)], 'reference_source': "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\nconst values = lines[0].split(' ').map(Number);\nconst target = Number(lines[1]);\nconsole.log(values.includes(target));\n"},
    {'technology': 'javascript', 'topic': 'objects', 'name': 'Create and Read an Object', 'slug': 'create-and-read-an-object', 'description': "Read a name and an age, space-separated. Build an object with keys name and age, then print name followed by a space and age, read back from the object's properties.", 'input_format': 'One line containing a name and an age, space-separated.', 'output_format': 'Print NAME AGE.', 'constraints': 'None.', 'examples': [{'input': 'Alice 30', 'output': 'Alice 30'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 1, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst [name, age] = input.split(' ');\nconst person = { name: name, age: Number(age) };\n// Print person.name and person.age, space-separated\n", 'tests': [('Alice 30\n', 'Alice 30\n', False, 1), ('Bo 9\n', 'Bo 9\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst [name, age] = input.split(' ');\nconst person = { name: name, age: Number(age) };\nconsole.log(person.name + ' ' + person.age);\n"},
    {'technology': 'javascript', 'topic': 'objects', 'name': 'Object Destructuring', 'slug': 'object-destructuring', 'description': 'An object { a: 5, b: 10 } is already defined. Destructure its a and b properties into variables and print their sum, with no input required.', 'input_format': 'There is no input for this problem.', 'output_format': 'Print a + b (15).', 'constraints': 'None.', 'examples': [{'input': '', 'output': '15'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 2, 'starter': 'const obj = { a: 5, b: 10 };\nconst { a, b } = obj;\n// Print a + b\n', 'tests': [('', '15\n', False, 1)], 'reference_source': 'const obj = { a: 5, b: 10 };\nconst { a, b } = obj;\nconsole.log(a + b);\n'},
    {'technology': 'javascript', 'topic': 'objects', 'name': 'Object.keys and Object.values', 'slug': 'object-keys-and-object-values', 'description': 'Read a name and a score, space-separated. Build an object with those two keys (name, score), then print its keys joined by a comma, and its values joined by a comma, on two separate lines.', 'input_format': 'One line containing a name and a score, space-separated.', 'output_format': 'Print the keys line, then the values line.', 'constraints': 'None.', 'examples': [{'input': 'Ana 90', 'output': 'name,score\nAna,90'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 3, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst [name, score] = input.split(' ');\nconst obj = { name: name, score: Number(score) };\n// Print Object.keys(obj).join(','), then Object.values(obj).join(',')\n", 'tests': [('Ana 90\n', 'name,score\nAna,90\n', False, 1), ('Ben 5\n', 'name,score\nBen,5\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst [name, score] = input.split(' ');\nconst obj = { name: name, score: Number(score) };\nconsole.log(Object.keys(obj).join(','));\nconsole.log(Object.values(obj).join(','));\n"},
