    {'technology': 'javascript', 'topic': 'array-methods', 'name': 'sort in Ascending Order', 'slug': 'sort-in-ascending-order', 'description': 'Read a line of space-separated integers and print them sorted from lowest to highest, space-separated. Provide a numeric comparator so sort works correctly for numbers.', 'input_format': 'One line of space-separated integers.', 'output_format': 'Print the sorted values, space-separated.', 'constraints': 'None.', 'examples': [{'input': '3 1 2', 'output': '1 2 3'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 5, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst values = input.split(' ').map(Number);\n// Sort ascending with a numeric comparator, then print\n", 'tests': [('3 1 2\n', '1 2 3\n', False, 1), ('10 2 33\n', '2 10 33\n', True, 2), ('-1 -5 0\n', '-5 -1 0\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst values = input.split(' ').map(Number);\nvalues.sort((a, b) => a - b);\nconsole.log(values.join(' '));\n"},
    {'technology': 'javascript', 'topic': 'promises', 'name': 'Resolve a Promise', 'slug': 'resolve-a-promise', 'description': 'Read one integer, wrap it in a Promise that resolves with that value doubled, then print the resolved value using .then.', 'input_format': 'One integer n.', 'output_format': 'Print n doubled.', 'constraints': 'None.', 'examples': [{'input': '5', 'output': '10'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 1, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\n// Create a Promise that resolves with n * 2, then .then(...) to print it\n", 'tests': [('5\n', '10\n', False, 1), ('-3\n', '-6\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\nconst doubled = new Promise((resolve) => resolve(n * 2));\ndoubled.then((value) => console.log(value));\n"},
    {'technology': 'javascript', 'topic': 'promises', 'name': 'Chain Two Promises', 'slug': 'chain-two-promises', 'description': 'Read one integer, resolve a Promise with it, then chain a .then that adds 1, then another .then that prints the final value.', 'input_format': 'One integer n.', 'output_format': 'Print n + 1.', 'constraints': 'None.', 'examples': [{'input': '5', 'output': '6'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 2, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\n// Promise.resolve(n).then(add 1).then(print)\n", 'tests': [('5\n', '6\n', False, 1), ('-1\n', '0\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\nPromise.resolve(n)\n  .then((value) => value + 1)\n  .then((value) => console.log(value));\n"},
    {'technology': 'javascript', 'topic': 'promises', 'name': 'Promise.all', 'slug': 'promise-all-js', 'description': 'Read two integers, space-separated. Wrap each in a resolved Promise, use Promise.all to wait for both, then print their sum.', 'input_format': 'One line containing two integers a and b.', 'output_format': 'Print a + b.', 'constraints': 'None.', 'examples': [{'input': '3 4', 'output': '7'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 3, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst [a, b] = input.split(' ').map(Number);\n// Promise.all([Promise.resolve(a), Promise.resolve(b)]).then(print their sum)\n", 'tests': [('3 4\n', '7\n', False, 1), ('-2 5\n', '3\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst [a, b] = input.split(' ').map(Number);\nPromise.all([Promise.resolve(a), Promise.resolve(b)])\n  .then((values) => console.log(values[0] + values[1]));\n"},
    {'technology': 'javascript', 'topic': 'promises', 'name': 'Catch a Rejected Promise', 'slug': 'catch-a-rejected-promise', 'description': "Read one integer. If it is negative, reject a Promise with the message 'negative'; otherwise resolve with the value. Print the resolved value, or print the word negative if it was caught with .catch.", 'input_format': 'One integer n.', 'output_format': 'Print n, or the word negative if n was negative.', 'constraints': 'None.', 'examples': [{'input': '5', 'output': '5'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 4, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\n// Resolve with n, or reject with 'negative' if n < 0; .then to print, .catch to print the error\n", 'tests': [('5\n', '5\n', False, 1), ('-3\n', 'negative\n', False, 1), ('0\n', '0\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\nnew Promise((resolve, reject) => {\n  if (n < 0) {\n    reject('negative');\n  } else {\n    resolve(n);\n  }\n})\n  .then((value) => console.log(value))\n  .catch((err) => console.log(err));\n"},
    {'technology': 'javascript', 'topic': 'promises', 'name': 'A Promise-Returning Function', 'slug': 'a-promise-returning-function', 'description': 'Write a function double(n) that returns a Promise resolving with n * 2. Read one integer, call double, and print the resolved value.', 'input_format': 'One integer n.', 'output_format': 'Print n doubled.', 'constraints': 'None.', 'examples': [{'input': '5', 'output': '10'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 5, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nfunction double(n) {\n  // Return a Promise that resolves with n * 2\n}\ndouble(Number(input)).then((value) => console.log(value));\n", 'tests': [('5\n', '10\n', False, 1), ('-3\n', '-6\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nfunction double(n) {\n  return new Promise((resolve) => resolve(n * 2));\n}\ndouble(Number(input)).then((value) => console.log(value));\n"},
    {'technology': 'javascript', 'topic': 'async-await', 'name': 'An Async Function', 'slug': 'an-async-function', 'description': 'Write an async function double(n) that returns n * 2 (an async function automatically wraps its return value in a Promise). Read one integer, await double, and print the result.', 'input_format': 'One integer n.', 'output_format': 'Print n doubled.', 'constraints': 'None.', 'examples': [{'input': '5', 'output': '10'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 1, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nasync function double(n) {\n  // Return n * 2\n}\nasync function main() {\n  console.log(await double(Number(input)));\n}\nmain();\n", 'tests': [('5\n', '10\n', False, 1), ('-3\n', '-6\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nasync function double(n) {\n  return n * 2;\n}\nasync function main() {\n  const result = await double(Number(input));\n  console.log(result);\n}\nmain();\n"},
    {'technology': 'javascript', 'topic': 'async-await', 'name': 'Awaiting Multiple Values in Sequence', 'slug': 'awaiting-multiple-values-in-sequence', 'description': 'Read two integers, space-separated. Write an async function that awaits each one (wrapped in Promise.resolve) in sequence and prints their sum.', 'input_format': 'One line containing two integers a and b.', 'output_format': 'Print a + b.', 'constraints': 'None.', 'examples': [{'input': '3 4', 'output': '7'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 2, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst [a, b] = input.split(' ').map(Number);\nasync function main() {\n  // await each value, then print their sum\n}\nmain();\n", 'tests': [('3 4\n', '7\n', False, 1), ('-2 5\n', '3\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst [a, b] = input.split(' ').map(Number);\nasync function main() {\n  const x = await Promise.resolve(a);\n  const y = await Promise.resolve(b);\n  console.log(x + y);\n}\nmain();\n"},
    {'technology': 'javascript', 'topic': 'async-await', 'name': 'Try/Catch With Await', 'slug': 'try-catch-with-await', 'description': 'Read one integer. Write an async function that awaits a Promise which rejects if the value is negative, using try/catch to print the value, or the word negative if it was caught.', 'input_format': 'One integer n.', 'output_format': 'Print n, or negative if n was negative.', 'constraints': 'None.', 'examples': [{'input': '5', 'output': '5'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 3, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\nasync function main() {\n  // try { await ... ; print } catch (err) { print err }\n}\nmain();\n", 'tests': [('5\n', '5\n', False, 1), ('-3\n', 'negative\n', False, 1), ('0\n', '0\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\nasync function main() {\n  try {\n    const value = await new Promise((resolve, reject) => {\n      if (n < 0) {\n        reject('negative');\n      } else {\n        resolve(n);\n      }\n    });\n    console.log(value);\n  } catch (err) {\n    console.log(err);\n  }\n}\nmain();\n"},
    {'technology': 'javascript', 'topic': 'async-await', 'name': 'Awaiting in a Loop', 'slug': 'awaiting-in-a-loop', 'description': 'Read a line of space-separated integers. Write an async function that awaits each value (wrapped in Promise.resolve) in a for loop, accumulating their sum, then prints the total.', 'input_format': 'One line of space-separated integers.', 'output_format': 'Print their sum.', 'constraints': 'None.', 'examples': [{'input': '1 2 3', 'output': '6'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 4, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst values = input.split(' ').map(Number);\nasync function main() {\n  // await each value in a loop, accumulate, then print the total\n}\nmain();\n", 'tests': [('1 2 3\n', '6\n', False, 1), ('-5 5 10\n', '10\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst values = input.split(' ').map(Number);\nasync function main() {\n  let total = 0;\n  for (const value of values) {\n    total += await Promise.resolve(value);\n  }\n  console.log(total);\n}\nmain();\n"},
    {'technology': 'javascript', 'topic': 'async-await', 'name': 'An Async Function Returning an Object', 'slug': 'an-async-function-returning-an-object', 'description': 'Read a name and a score, space-separated. Write an async function that returns an object { name, score }. Await it and print name followed by a space and score.', 'input_format': 'One line containing a name and a score, space-separated.', 'output_format': 'Print NAME SCORE.', 'constraints': 'None.', 'examples': [{'input': 'Ana 90', 'output': 'Ana 90'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 5, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst [name, score] = input.split(' ');\nasync function build() {\n  // Return { name, score: Number(score) }\n}\nasync function main() {\n  const result = await build();\n  console.log(result.name + ' ' + result.score);\n}\nmain();\n", 'tests': [('Ana 90\n', 'Ana 90\n', False, 1), ('Ben 5\n', 'Ben 5\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst [name, score] = input.split(' ');\nasync function build() {\n  return { name: name, score: Number(score) };\n}\nasync function main() {\n  const result = await build();\n  console.log(result.name + ' ' + result.score);\n}\nmain();\n"},
    {'technology': 'javascript', 'topic': 'error-handling', 'name': 'Try and Catch', 'slug': 'try-and-catch-js', 'description': 'Read one line of text. Attempt to JSON.parse it inside a try block; if it throws, catch the error and print invalid, otherwise print valid.', 'input_format': 'One line of text (may or may not be valid JSON).', 'output_format': 'Print valid or invalid.', 'constraints': 'None.', 'examples': [{'input': '{"a":1}', 'output': 'valid'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 1, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\n// Try JSON.parse(input); print 'valid' or 'invalid' via try/catch\n", 'tests': [('{"a":1}\n', 'valid\n', False, 1), ('not json\n', 'invalid\n', False, 1), ('[1,2,3]\n', 'valid\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\ntry {\n  JSON.parse(input);\n  console.log('valid');\n} catch (err) {\n  console.log('invalid');\n}\n"},
    {'technology': 'javascript', 'topic': 'error-handling', 'name': 'Throw a Custom Error', 'slug': 'throw-a-custom-error', 'description': "Write a function checkPositive(n) that throws an Error with message 'must be positive' if n is not greater than 0, otherwise returns n. Read one integer, call checkPositive inside a try/catch, and print the result or the caught error's message.", 'input_format': 'One integer n.', 'output_format': "Print n, or the caught error's message.", 'constraints': 'None.', 'examples': [{'input': '5', 'output': '5'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 2, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nfunction checkPositive(n) {\n  // Throw new Error('must be positive') if n <= 0, else return n\n}\ntry {\n  console.log(checkPositive(Number(input)));\n} catch (err) {\n  console.log(err.message);\n}\n", 'tests': [('5\n', '5\n', False, 1), ('-3\n', 'must be positive\n', False, 1), ('0\n', 'must be positive\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nfunction checkPositive(n) {\n  if (n <= 0) {\n    throw new Error('must be positive');\n  }\n  return n;\n}\ntry {\n  console.log(checkPositive(Number(input)));\n} catch (err) {\n  console.log(err.message);\n}\n"},
    {'technology': 'javascript', 'topic': 'error-handling', 'name': 'The finally Block', 'slug': 'the-finally-block', 'description': 'Read one integer. Inside a try/catch/finally, print Attempting in the try block before doing anything risky, then print the value; the finally block should always print Done, whether or not an error occurred (this input never errors).', 'input_format': 'One integer n.', 'output_format': 'Print Attempting, then n, then Done, each on its own line.', 'constraints': 'None.', 'examples': [{'input': '5', 'output': 'Attempting\n5\nDone'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 3, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\ntry {\n  console.log('Attempting');\n  console.log(Number(input));\n} finally {\n  console.log('Done');\n}\n", 'tests': [('5\n', 'Attempting\n5\nDone\n', False, 1), ('-3\n', 'Attempting\n-3\nDone\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\ntry {\n  console.log('Attempting');\n  console.log(Number(input));\n} finally {\n  console.log('Done');\n}\n"},
    {'technology': 'javascript', 'topic': 'error-handling', 'name': 'A Custom Error Class', 'slug': 'a-custom-error-class', 'description': 'Define a class ValidationError extending Error. Write a function checkRange(n) that throws a ValidationError if n is outside 1 to 10, otherwise returns n. Read one integer and print the result, or print out of range if a ValidationError was caught.', 'input_format': 'One integer n.', 'output_format': 'Print n, or out of range.', 'constraints': 'None.', 'examples': [{'input': '5', 'output': '5'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 4, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nclass ValidationError extends Error {}\nfunction checkRange(n) {\n  // Throw new ValidationError('out of range') if n < 1 or n > 10, else return n\n}\ntry {\n  console.log(checkRange(Number(input)));\n} catch (err) {\n  if (err instanceof ValidationError) {\n    console.log('out of range');\n  } else {\n    throw err;\n  }\n}\n", 'tests': [('5\n', '5\n', False, 1), ('15\n', 'out of range\n', False, 1), ('0\n', 'out of range\n', True, 2), ('10\n', '10\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nclass ValidationError extends Error {}\nfunction checkRange(n) {\n  if (n < 1 || n > 10) {\n    throw new ValidationError('out of range');\n  }\n  return n;\n}\ntry {\n  console.log(checkRange(Number(input)));\n} catch (err) {\n  if (err instanceof ValidationError) {\n    console.log('out of range');\n  } else {\n    throw err;\n  }\n}\n"},
    {'technology': 'javascript', 'topic': 'error-handling', 'name': 'Rethrow After Cleanup', 'slug': 'rethrow-after-cleanup', 'description': "Read one integer. Write code that, inside try/catch, throws an Error with message 'bad input' if the value is 0, catches it, prints Cleaning up, then rethrows so the error propagates -- wrap the whole thing in an outer try/catch that prints the rethrown message. If the value is not 0, just print the value.", 'input_format': 'One integer n.', 'output_format': 'Print n; or, if n is 0, print Cleaning up then bad input.', 'constraints': 'None.', 'examples': [{'input': '5', 'output': '5'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 5, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\n// Inner try/catch: throw if n===0, catch, print 'Cleaning up', rethrow.\n// Outer try/catch: print n normally, or the rethrown message.\n", 'tests': [('5\n', '5\n', False, 1), ('0\n', 'Cleaning up\nbad input\n', False, 1), ('-3\n', '-3\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\ntry {\n  try {\n    if (n === 0) {\n      throw new Error('bad input');\n    }\n    console.log(n);\n  } catch (err) {\n    console.log('Cleaning up');\n    throw err;\n  }\n} catch (err) {\n  console.log(err.message);\n}\n"},
